    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
    String username = nameField.getText().trim();
    
    // Enforce mandatory name field validation check
    if (username.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Access Denied: Please enter your name first!");
        return;
    }
    
    // Pass the name cleanly into the second frame window constructor
    BicycleGUI calculatorWindow = new BicycleGUI(username);
    calculatorWindow.setVisible(true);
    }//GEN-LAST:event_jButton1ActionPerformed

    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        String username = nameField.getText().trim();
    
    if (username.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this, "Access Denied: Please enter your name first!");
        return;
    }
    
    MushroomGUI mushroomWindow = new MushroomGUI(username);
    mushroomWindow.setVisible(true);
    }//GEN-LAST:event_jButton2ActionPerformed

